// <auto-generated />
using System.Collections.Generic;
using Fanex.Excel.Enums;
using Fanex.Excel.Models;
using Newtonsoft.Json;
using RiskControl.NonSportsGamesStatistics.Common;
using RiskControl.NonSportsGamesStatistics.Model;
using RiskControl.NonSportsGamesStatistics.TopTwenty.Common;

namespace RiskControl.NonSportsGamesStatistics.TopTwenty.Main
{
    public class GridOptionBuilderServiceImp<TQueryModel> : GridOptionBuilderService<List<UserNameViewGroupStatisticsWithTotalModel>, TQueryModel>
        where TQueryModel: BaseStatisticQueryModel
    {
        private const int CustIdColumnIndex = 1;
        private readonly GridOptionDataRowBuilderService gridDataRowBuilderService;
        private readonly GridOptionRemoveColumnService gridOptionRemoveColumnService;
        private readonly GridOptionHeaderBuilderService headerBuilderService;

        public GridOptionBuilderServiceImp(
            GridOptionDataRowBuilderService gridDataRowBuilderService,
            GridOptionHeaderBuilderService headerBuilderService,
            GridOptionRemoveColumnService gridOptionRemoveColumnService)
        {
            this.gridDataRowBuilderService = gridDataRowBuilderService;
            this.headerBuilderService = headerBuilderService;
            this.gridOptionRemoveColumnService = gridOptionRemoveColumnService;
        }

        public GridOptions BuildGridOptions(List<UserNameViewGroupStatisticsWithTotalModel> statistics,
            TQueryModel queryModel)
        {
            var gridOptions = new GridOptions
            {
                ShowTitle = true,
                TitleType = TitleType.TwoLineBlue,
                TitleInfoText = queryModel.Title,
                BodyRows = BuildBodyRows(statistics, queryModel.IsNormalMode, queryModel.ViewByInteger),
                Columns = BuildHeaderColumns(queryModel),
                ShowFooter = false,
                ShowHighlightRow = false,
                ShowDistinctRow = false,
                ShowTree = true
            };

            gridOptions = gridOptionRemoveColumnService.RemoveColumn(gridOptions, queryModel.RemovalColumns);

            return gridOptions;
        }

        private List<HeaderColumns> BuildHeaderColumns(BaseStatisticQueryModel queryModel)
        {
            var headerColumns = headerBuilderService.BuildBaseHeaderColumns(queryModel);

            if (headerColumns != null)
            {
                headerColumns.Insert(CustIdColumnIndex,
                    new HeaderColumns { Name = "ReportById", HeaderText = "CustID", Width = 100 });
                if (queryModel.IsNormalMode)
                {
                    headerColumns.Add(new HeaderColumns
                    {
                        HeaderText = "House PT",
                        Width = 80,
                        Name = "HousePositionTaking",
                        CustomCellType = ExcelCellType.Percentage,
                        Sort = true,
                        SortDirection =
                            queryModel.SortColumnName == "HousePositionTaking" ? queryModel.SortDirection : string.Empty
                    });
                }

                headerColumns.Add(new HeaderColumns
                {
                    HeaderText = "Associated Accounts",
                    Width = 150,
                    Name = "AssociatedAccounts"
                });
            }

            return headerColumns;
        }

        private List<GridDataRow> BuildBodyRows(List<UserNameViewGroupStatisticsWithTotalModel> statistics,
            bool isNormalMode, bool viewByInteger)
        {
            var dataRows = new List<GridDataRow>();
            foreach (var group in statistics)
            {
                var totalRow = gridDataRowBuilderService.BuildMainDataRow(group.Total, isNormalMode, viewByInteger);
                var customGroupAttributes =
                    new
                    {
                        groupId = group.Total.ReportById,
                        groupName = group.Total.ReportBy,
                        currency = group.Total.CurrencyId
                    };
                totalRow.CustomAttr = JsonConvert.SerializeObject(customGroupAttributes);
                totalRow.RowType = RowType.ParentLevelOne;
                totalRow.Columns.ForEach(x => x.Bold = true);
                foreach (var item in group.Statistics)
                {
                    var groupDataRow = gridDataRowBuilderService.BuildMainGroupDataRow(item, isNormalMode, viewByInteger);
                    totalRow.SubRows.AddRange(groupDataRow);
                }

                dataRows.Add(totalRow);
            }

            return dataRows;
        }
    }
}